class ImmutableHelper:
    def __init__(self, obj):
        self._root = obj

    def produce(self, mutator):
        # Copy-on-write with structural sharing: a container is shallow-copied
        # only when it (or something below it) is first changed.
        class Node:
            def __init__(self, orig, parent=None, key=None):
                self.orig = orig        # original container (never modified)
                self.parent = parent
                self.key = key          # key/index of this node inside its parent
                self.copy = None        # shallow copy, created lazily on first write
                self.children = {}      # key -> Node for nested containers already accessed

            def current(self):
                return self.orig if self.copy is None else self.copy

            def ensure_copy(self):
                if self.copy is None:
                    self.copy = dict(self.orig) if isinstance(self.orig, dict) else list(self.orig)
                    if self.parent is not None:
                        # copy every ancestor too, and point it at the new child
                        self.parent.ensure_copy()[self.key] = self.copy
                return self.copy

        class Proxy:
            def __init__(self, node):
                object.__setattr__(self, "_node", node)

            def _get(self, key):
                node = self._node
                value = node.current()[key]
                if not isinstance(value, (dict, list)):
                    return value
                child = node.children.get(key)
                if child is None:
                    child = node.children[key] = Node(value, node, key)
                return Proxy(child)

            def _set(self, key, value):
                node = self._node
                target = node.current()
                if isinstance(target, dict):
                    exists = key in target
                else:
                    exists = isinstance(key, int) and 0 <= key < len(target)
                if not exists:
                    raise KeyError("Setting new keys is not allowed")
                old = target[key]
                if old is value or (not isinstance(old, (dict, list))
                                    and type(old) is type(value) and old == value):
                    return  # same value: no cloning needed
                node.ensure_copy()[key] = value
                node.children.pop(key, None)  # any cached child proxy is now stale

            def __getitem__(self, key):
                return self._get(key)

            def __setitem__(self, key, value):
                self._set(key, value)

            def __getattr__(self, key):
                if isinstance(self._node.orig, dict) and key in self._node.current():
                    return self._get(key)
                raise AttributeError(key)

            def __setattr__(self, key, value):
                self._set(key, value)

            def __len__(self):
                return len(self._node.current())

        root = Node(self._root)
        mutator(Proxy(root))
        # Untouched root -> the original object itself; otherwise the copied path
        return root.current()
